package org.apache.commons.lang3.time;

import org.junit.Test;
import org.junit.Assert;
import java.util.Locale;
import java.util.TimeZone;

public class AgentBRT_Lang_9_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        String pattern = "yyyy-MM-dd'T'HH:mm:ss.SSSZ";
        TimeZone timeZone = TimeZone.getTimeZone("UTC");
        Locale locale = Locale.US;

        FastDateParser parser = new FastDateParser(pattern, timeZone, locale);

        // The expected behavior is that the parse pattern should be correctly initialized
        // and should not be null or malformed.
        Assert.assertNotNull("Parse pattern should not be null", parser.getParsePattern());
        Assert.assertTrue("Parse pattern should contain expected regex",
                parser.getParsePattern().pattern().contains("\\d{4}-\\d{2}-\\d{2}"));
    }
}

